```python
import time
import random
import functools

class CircuitBreaker:
    def __init__(self, failure_threshold=5, recovery_time=30):
        self.failure_threshold = failure_threshold
        self.recovery_time = recovery_time
        self.failure_count = 0
        self.last_failure_time = None
        self.state = 'CLOSED'  # States: CLOSED, OPEN, HALF_OPEN

    def call(self):
        if self.state == 'OPEN':
            if time.time() - self.last_failure_time > self.recovery_time:
                self.state = 'HALF_OPEN'
            else:
                raise Exception("Circuit is open, request denied.")

    def record_failure(self):
        self.failure_count += 1
        self.last_failure_time = time.time()
        if self.failure_count >= self.failure_threshold:
            self.state = 'OPEN'

    def record_success(self):
        self.failure_count = 0
        self.state = 'CLOSED'


def retry_with_exponential_backoff(max_retries=5, base_delay=1.0, max_delay=60.0):
    circuit_breaker = CircuitBreaker()

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal circuit_breaker
            retries = 0

            while True:
                try:
                    # Check the circuit breaker before attempting the function
                    circuit_breaker.call()
                    result = func(*args, **kwargs)
                    circuit_breaker.record_success()  # Record success if function call is successful
                    return result
                except Exception as e:
                    print(f"Attempt {retries + 1} failed: {e}")
                    circuit_breaker.record_failure()  # Record failure for the circuit breaker

                    if retries >= max_retries:
                        print("Max retries reached, raising exception.")
                        raise

                    # Calculate backoff delay with jitter
                    delay = min(base_delay * (2 ** retries), max_delay) + random.uniform(0, base_delay)
                    print(f"Retrying in {delay:.2f} seconds...")
                    time.sleep(delay)
                    retries += 1

        return wrapper

    return decorator

