### Run-Length Encoding (RLE) Compression and Decompression

```javascript
function compress(input) {
    if (!input) return "";

    let compressed = "";
    let count = 1;

    for (let i = 0; i < input.length; i++) {
        // Check if the next character is the same as the current
        if (i < input.length - 1 && input[i] === input[i + 1]) {
            count++;
        } else {
            compressed += input[i] + count;
            count = 1; // Reset count
        }
    }

    return compressed;
}

function decompress(compressed) {
    if (!compressed) return "";

    let decompressed = "";
    let i = 0;

    while (i < compressed.length) {
        const char = compressed[i]; // Current character
        i++;
        let countStr = "";

        // Get the full number following the character
        while (i < compressed.length && !isNaN(compressed[i])) {
            countStr += compressed[i];
            i++;
        }

        const count = parseInt(countStr, 10);
        decompressed += char.repeat(count); // Repeat the character by count
    }

    return decompressed;
}

// Example Usage
const originalString = "aaabbbcccdde";
const compressedString = compress(originalString);
const decompressedString = decompress(compressedString);

console.log("Original String:", originalString);
console.log("Compressed String:", compressedString);
console.log("Decompressed String:", decompressedString);
```

