function compress(input) {
    if (typeof input !== 'string') {
        throw new Error("Input must be a string");
    }
    if (input.length === 0) {
        return ""; // Handle empty string
    }

    let compressed = [];
    let count = 1;

    for (let i = 1; i <= input.length; i++) {
        if (input[i] === input[i - 1]) {
            count++;
        } else {
            compressed.push(input[i - 1]);
            compressed.push(count);
            count = 1;
        }
    }

    // Join the array to form the final compressed string
    const compressedString = compressed.join('');

    // Return original string if compressed version is not shorter
    return compressedString.length < input.length ? compressedString : input;
}

function decompress(input) {
    if (typeof input !== 'string') {
        throw new Error("Input must be a string");
    }
    if (input.length === 0) {
        return ""; // Handle empty string
    }

    let decompressed = [];
    let i = 0;

    while (i < input.length) {
        let char = input[i];
        i++;
        let count = '';

        // Collect digits for multi-digit counts
        while (i < input.length && !isNaN(input[i])) {
            count += input[i];
            i++;
        }

        // Convert count string to number and repeat character
        decompressed.push(char.repeat(Number(count)));
    }

    return decompressed.join('');
}

